    public IconView(string key)
    {
        Key = key;
        Width = Height = 20;
        var path = new Path { Data = Geometry.Parse(Shapes.GetValueOrDefault(key, Shapes["Info"])), StrokeThickness = 1.75, StrokeLineCap = PenLineCap.Round, StrokeJoin = PenLineJoin.Round };
        if (key == "GPT") { path.StrokeThickness = 0; path.Bind(Path.FillProperty, this.GetObservable(ForegroundProperty)); }
        else path.Bind(Path.StrokeProperty, this.GetObservable(ForegroundProperty));
        Content = new Viewbox { Child = new Canvas { Width = 24, Height = 24, Children = { path } } };
    }
